use conduit_core::{StructuredInfoType,StructuredInfoTypeShape};
use conduit_plot::{parse_syntax_document,check_syntax_document,StartupCatalog,expand_canonical_plot_for_authoring,ProfileCatalog};
fn td(t:&StructuredInfoType)->usize{1+match t.shape(){StructuredInfoTypeShape::Leaf(_)=>0,StructuredInfoTypeShape::Nominal{representation,..}=>td(representation),StructuredInfoTypeShape::Collection{element,..}|StructuredInfoTypeShape::Sequence{element,..}=>td(element),StructuredInfoTypeShape::Record{fields,..}=>fields.iter().map(|f|td(f.value_type())).max().unwrap_or(0),StructuredInfoTypeShape::Variant{cases,..}=>cases.iter().map(|c|td(c.payload_type())).max().unwrap_or(0)}}
fn nd(n:&conduit_plot::PortableExpressionNode)->usize{use conduit_plot::PortableExpressionOperation::*;1+match &n.operation{Input|Literal(_)=>0,Projection{value,..}=>nd(value),Unary{operand,..}=>nd(operand),Binary{left,right,..}=>nd(left).max(nd(right)),Conditional{condition,when_true,when_false}=>nd(condition).max(nd(when_true)).max(nd(when_false)),Tuple(v)|Collection(v)=>v.iter().map(nd).max().unwrap_or(0),Record(v)=>v.iter().map(|(_,n)|nd(n)).max().unwrap_or(0),Variant{payload,..}=>nd(payload),SemanticCall{arguments,..}=>arguments.iter().map(nd).max().unwrap_or(0)}}
fn main(){
 let root=std::path::Path::new("/home/dancxjo/conduit-4907-evaluation-identity/semantics/language");
 let source=["types","identity","coverage","syntax","text_revision","lexical","lexical_proposer","parser","parser_mask","parser_window8","parser_window8_search","parser_window8_facts"].iter().map(|n|std::fs::read_to_string(root.join(format!("{n}.conduit"))).unwrap()).collect::<Vec<_>>().join("\n");
 let source=source+"\n"+&std::fs::read_to_string("work/lexical-proposer-next/qualified_analysis.conduit").unwrap();
 let parsed=parse_syntax_document(&source);
 match check_syntax_document(&parsed,&StartupCatalog::new()) {Ok(c)=>{println!("PASS checked_native_types={}",c.native_types.len());for t in &c.native_types{if t.name.contains("QualifiedLexical"){println!("type={} depth={} canonical_bytes={} laws={}",t.name,td(&t.value_type),t.value_type.canonical_bytes().unwrap().len(),t.invariants.len());for (i,p)in t.invariants.iter().enumerate(){println!("law={i} ast_depth={} bytes={}",nd(&p.root),p.canonical_bytes().unwrap().len());}}}match expand_canonical_plot_for_authoring(&c,"language-window8-qualified-lexical-proposal",&ProfileCatalog::new()){Ok(_)=>println!("PASS qualified-port-expansion"),Err(e)=>{eprintln!("{e:#?}");std::process::exit(2)}}},Err(e)=>{eprintln!("{e:#?}");std::process::exit(1)}}
}
